 panel('本轮检索调度',t.selection_audit?.retrieval_policy?`<dl class="field-grid"><dt>内置外部向量</dt><dd>${esc(t.selection_audit.retrieval_policy.remote_vector==='attempt'?'已安排查询（不等于命中）':'本轮未调用')}</dd><dt>原因</dt><dd>${esc(({configured_default:'已授权默认查询',administrator_disabled:'管理员停用',not_configured:'未配置',trusted_host_declined:'可信宿主建议跳过'})[t.selection_audit.retrieval_policy.reason]||t.selection_audit.retrieval_policy.reason)}</dd></dl>`:empty('历史记录未采集调度策略'))+
 (t.upstream_submitted===true?'<div class="audit-note">网关记录上游 HTTP 响应；不代表模型理解或采用了记忆。</div>':t.request_snapshot_verified===true?'<div class="audit-note">请求快照已核验；尚无上游响应回执，不能标记为已注入。</div>':'<div class="screen-alert" role="status">未发现真实模型请求读回证明。本轮不能标记为已注入。</div>')+
 panel('本轮信息',`<dl class="field-grid">${[['追踪 ID',t.trace_id||trace],['时间',t.at],['提问',t.asked],['实际请求读回',t.actual_request_verified===true?'宿主报告已核验':'未核验'],['请求快照',t.request_snapshot_verified===true?'快照已核验（非上游提交）':'未核验'],['上游提交',t.upstream_submitted===true?'受信网关响应回执（非独立证明）':'无响应回执'],['证明说明',t.verification_note]].map(([a,b])=>kv(a,b)).join('')}</dl>`)+panel('网关 HTTP 响应回执',(t.transport_receipts||[]).map(r=>`<div class="version-row"><strong>HTTP ${esc(r.upstream_status)}</strong><small>${esc(r.at)} · 请求摘要 ${esc(r.body_hash)}</small></div>`).join('')||empty('尚无网关响应回执'))+panel('召回资源与去重审计',t.selection_audit?`<dl class="field-grid">${[['候选数',t.selection_audit.candidate_count],['计划选中',t.selection_audit.selected_count],['召回正文 UTF-8 字节（不含其他网关上下文）',t.selection_audit.recall_envelope_utf8_bytes],['选择预算（字节）',t.selection_audit.budget_bytes??'未配置'],['精确去重',t.selection_audit.budget_lane?.deduplicated??'未记录'],['预算舍弃组',t.selection_audit.budget_lane?.omitted_groups??'未记录'],['人物联想激活方式',({topic_evidence:'话题证据',broad_person:'宽泛人物线索'})[t.selection_audit.association_lane?.activation]??'未激活或历史未记录'],['人物联想话题命中',t.selection_audit.association_lane?.topic_hits??'未记录'],['未填充联想名额',t.selection_audit.association_lane?.unfilled_slots??'未记录'],['人物跨库证据候选',t.selection_audit.association_lane?.associated_hits??'未记录'],['话题相关性延后（本地候选）',t.selection_audit.relevance_lane?.deferred_local_count??'未激活或历史未记录'],['实际 Token','未计量（字节不是 Token）']].map(([a,b])=>kv(a,b)).join('')}</dl>`:empty('历史记录未采集资源审计'))+list('检索范围 · checked',t.checked)+list('召回候选 · recalled',t.recalled)+list('计划选中 · selected',t.selected)+list('舍弃条目 · dropped');
