 `<div class="library-grid">${Object.entries(MODS).map(([id,[name]])=>`<button class="lib-tile" data-route="/module/${id}">${ico('spark')}<strong>${esc(name)}</strong><small>${modules[id]?.available?modules[id].count+' 条':'未接入'}</small></button>`).join('')}</div>`;
