async function moduleDetail(name,q){
 if(!MODS[name])return missing();
 const pageNum=Math.max(1,Number(q.get('page')||1)||1), limit=20;
 const d=await api(`/api/module?name=${uri(name)}&limit=${limit}&offset=${(pageNum-1)*limit}`);
 if(!d.available)return heading('Module / '+name,MODS[name][0],MODS[name][1])+panel('模块尚未启用',`<p class="muted">${esc(d.note||'当前实例未启用该模块。不使用演示内容伪装。')}</p>`);
 const isObservation=['domains','env','vitals'].includes(name),isVital=name==='vitals';
 const st=isObservation?await ensureStatus():null;
 const form=isObservation&&st?.writes_enabled?fold('手动补登观察',`<form id="observationCreate" data-name="${esc(name)}"><label>观察分类<select name="category" required><option value="">请选择</option>${Object.entries((({domains:{work:"工作",learning:"学习",skill:"技能",interest:"兴趣"},env:{physical:"物理环境",digital:"数字环境",social:"社交环境",routine:"日常环境"},vitals:{sleep:"睡眠",activity:"活动",nutrition:"饮食",self_report:"身体自述"}})[name]||{})).map(([k,v])=>`<option value="${esc(k)}">${esc(v)}</option>`).join("")}<option value="custom">自定义</option></select></label><label>自定义分类名（仅自定义填写）<input name="category_label" maxlength="60"></label><label>标题<input name="title" required maxlength="120" placeholder="${isVital?'例如：自述睡眠时长':name==='domains'?'例如：项目开发经验':'例如：工作环境变化'}"></label><label>记录内容<textarea name="detail" required maxlength="2000" rows="3"></textarea></label><label>实际观察时间<input type="datetime-local" name="observed_at" required></label>${isVital?'<label>自述或设备来源<input name="source_ref" required maxlength="200"></label><label class="observation-consent"><input type="checkbox" name="consent" required> 我明确同意单独加密保存此条身体读数</label>':window.EverlightExtras.sourceField()}<button class="soft-btn primary observation-save" type="submit">保存观察</button></form>`):'';
 const rows=(d.rows||[]).map((r,i)=>{
   const title=String(r.title||r.at||r.day||r.name||r.id||('记录 '+((pageNum-1)*limit+i+1)));
   return `<article class="human-record"><h3>${esc(title)}</h3>${typeof r.detail==='string'?`<p class="human-reading">${esc(r.detail)}</p>`:''}${r.observed_at?`<small>${esc(localTime(r.observed_at))}</small>`:''}<details><summary>来源与完整记录</summary><dl class="field-grid">${Object.entries(r).map(([k,v])=>kv(({title:'标题',detail:'内容',category:'观察分类',category_label:'自定义分类',observed_at:'观察时间',attribution:'归属',source_id:'来源 ID',source_ref:'来源说明',at:'记录时间',id:'编号'})[k]||k,typeof v==='object'&&v!==null?JSON.stringify(v):v)).join('')}</dl>${isObservation&&st?.writes_enabled?`<form class="observation-withdraw" data-name="${esc(name)}"><input type="hidden" name="id" value="${esc(r.id)}"><button type="submit" class="soft-btn danger">撤回记录</button></form>`:''}</details></article>`;
 }).join('');
 return heading('Module / '+name,MODS[name][0],MODS[name][1])+
   panel('模块数据',`<div class="meta">${d.total} 条 · 每页 ${limit} 条</div><p class="muted">${esc(d.note||'')}</p>${rows||empty('暂无记录')}`)+
   pagination(pageNum,d.total,limit,n=>`/module/${name}?page=${n}`)+form;
}
async function searchPage(q){const term=q.get('q')?.trim()||'',s=q.get('slot')||'',p=Math.max(1,Number(q.get('page')||1)||1),limit=25;let result='';
 if(term){const r=await api(`/api/search?q=${uri(term)}&limit=${limit}&offset=${(p-1)*limit}${s?'&slot='+uri(s):''}`);
 result=panel(`检索结果 · ${r.total}`,`<p class="hint">已查：${s?slot(s)[1]:'十二个逻辑库'} · 仅字面匹配，不等于语义召回。原话查正文与来源，回执查操作、对象、结果，召回账本查问题；不查夜契及历史快照。</p>${(r.rows||[]).map(x=>line(x,`/memory/${x.slot}/${uri(x.id)}`,slot(x.slot)[3])).join('')||empty('没有字面命中；不代表记忆不存在。')}`)+pagination(p,r.total,limit,n=>`/search?q=${uri(term)}${s?'&slot='+s:''}&page=${n}`);}
 return heading('Memory Search','检索记忆','按关键词与分卷检索，不隐藏未覆盖范围。')+
 panel('跨库正文关键词检索',`<form id="searchForm"><label>关键词</label><input type="search" name="q" maxlength="200" value="${esc(term)}" placeholder="输入记忆内容或来源关键词" required><label>分卷范围</label><select name="slot"><option value="">全部十二库</option>${SLOTS.map(([id,n])=>`<option value="${id}" ${s===id?'selected':''}>${n}</option>`).join('')}</select><div class="form-actions"><button type="submit" class="soft-btn primary">检索</button></div></form>`)+result;
}
