async function statusPage(){const [st,m,g]=await Promise.all([api('/api/status'),api('/api/modules'),api('/api/v8/ui/gateway-health').catch(()=>({state:'unknown'}))]);status=st;const entries=Object.entries(st.counts||{});const total=entries.reduce((sum,[,n])=>sum+Number(n||0),0);
 return heading('Instance Status','系统状态','连接信息、库统计和模块状态，全部读取当前实例')+
 panel('模型网关',`<div class="row-actions">${tag(({ready:'本地网关可达',disabled:'未启用',configuration_error:'配置不完整',unavailable:'无法连接',invalid_response:'响应格式异常',unknown:'未核验'})[g.state]||'未核验',g.state==='ready'?'good':'warn')}</div><p class="hint">${g.state==='ready'?'模型列表接口可达，共 '+Number(g.model_count||0)+' 个配置模型；并不证明上游模型可用。':'此结果仅反映当前配置与本地探测状态。'} 未验证实际模型送达。</p>${linkButton('刷新状态','/status')}`)+
 (st.auto_memory?panel('自动记忆活动',`<dl class="field-grid">${[['配置',st.auto_memory.configured?'已配置 · 不代表后台在线':st.auto_memory.enabled?'配置不完整':'未启用'],['已生成候选的来源',st.auto_memory.counts?.proposed||0],['无需沉淀',st.auto_memory.counts?.no_change||0],['任务自动记录',st.auto_memory.task_progress?.enabled?'已配置 · 待实际运行':'未确认开启'],['现行任务自动进展',st.auto_memory.task_progress?.events??'未提供'],['自动任务候选',st.auto_memory.extra_features?.task_intent?'已配置':'未确认开启'],['自动反思候选',st.auto_memory.extra_features?.reflection?'已配置':'未确认开启'],['完全重复',st.auto_memory.counts?.exact_repeat||0],['暂缓或排除',st.auto_memory.counts?.held||0],['等待重试',st.auto_memory.counts?.retry||0],['感知引擎',st.auto_memory.awareness?.enabled?'已启用':'未启用'],['待送达的感知提醒',st.auto_memory.awareness?.counts?.queued||0],['已确认接收但待处理',st.auto_memory.awareness?.counts?.acknowledged||0],['已核验处理',st.auto_memory.awareness?.counts?.resolved||0],['最近处理',st.auto_memory.last_activity||'暂无']].map(([a,b])=>kv(a,b)).join('')}</dl><p class="hint">自动候选不等于正式入库。此处为来源事件处理计数，非记忆条目数；未验证后台在线。</p>${linkButton('查看待审核','/reviews/pending')}`):'')+
 panel('我的数据',linkButton('记忆导出','/export'))+
 await governancePanel()+
 panel('运行概况',`<dl class="field-grid">${[['实例身份',st.identity?.name],['身份主体',st.identity?.subject],['身份来源状态',({explicit_canonical_name:'规范 S09 明确名称',ambiguous:'多个主体或名称冲突',no_explicit_name:'未登记明确名称'})[st.identity?.state]||st.identity?.state],['当前规范记忆行数',total],['逻辑库数量',entries.length],['可写状态',st.writes_enabled?'已授权':'只读'],['是否需要认证',st.auth_required?'是':'否'],['最近召回','需要进入审计页核对']].map(([a,b])=>kv(a,b)).join('')}</dl>`)+
 panel('各库记录行数',`<dl class="field-grid">${SLOTS.map(([id,n])=>kv(`${id} · ${n}`,st.ledger_counts?.[id]??st.counts?.[id]??0)).join('')}</dl>`)+
 panel('可选模块',`<dl class="field-grid">${Object.entries(MODS).map(([id,[name]])=>kv(name,m.modules?.[id]?.available?`已接入 · ${m.modules[id].count} 条`:'未接入')).join('')}</dl>`)+
 panel('接口与证据边界','<p class="muted">本面板使用真实 /api/ 接口，不存虚构编辑结果。若没有实际模型请求读回，仍然显示“未核验”。写入只在服务器开启授权后可用。</p>');
}
